class JournalError(ValueError):
    pass


def _is_id_list(value):
    return isinstance(value, list) and all(isinstance(item, str) and item for item in value)


def read_changes(records):
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
                or not isinstance(row.get("component"), str) or not row["component"]
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = row.get("depends_on", [])
        if not _is_id_list(depends_on):
            raise JournalError("invalid-change")
        identity = {"id": row["id"], "component": row["component"],
                    "units": row["units"], "depends_on": frozenset(depends_on)}
        previous = changes.get(row["id"])
        if previous is not None and previous != identity:
            raise JournalError("conflicting-change")
        if previous is None:
            changes[row["id"]] = identity
    return [dict(item, depends_on=sorted(item["depends_on"])) for item in changes.values()]


def read_applied(applied):
    if applied is None:
        return []
    if not _is_id_list(applied):
        raise JournalError("invalid-change")
    return list(dict.fromkeys(applied))

