"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes):
    """Kahn's algorithm, taking the lexicographically smallest eligible ID first."""
    by_id = {row["id"]: row for row in changes}
    pending = {change_id: 0 for change_id in by_id}
    dependents = {change_id: [] for change_id in by_id}
    for change in changes:
        for target in change["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
            dependents[target].append(change["id"])
            pending[change["id"]] += 1

    ready = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        order = _topological_order(changes)
        unknown = [change_id for change_id in applied if change_id not in set(order)]
        if unknown:
            raise JournalError("unknown-dependency")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_of = {row["id"]: row["units"] for row in changes}
    applied_set = set(applied)
    if request["action"] == "rollback":
        emitted = [change_id for change_id in reversed(order) if change_id in applied_set]
    else:
        emitted = [change_id for change_id in order if change_id not in applied_set]
        units = sum(units_of[change_id] for change_id in emitted)
        if units > budget:
            return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted,
            "units": sum(units_of[change_id] for change_id in emitted)}

