"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retained
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes):
    """Kahn's algorithm, taking the lexicographically smallest eligible ID first."""
    by_id = {row["id"]: row for row in changes}
    pending = {change_id: 0 for change_id in by_id}
    dependents = {change_id: [] for change_id in by_id}
    for change in changes:
        for target in change["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
            dependents[target].append(change["id"])
            pending[change["id"]] += 1

    ready = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        change_id = heapq.heappop(ready)
        order.append(change_id)
        for dependent in dependents[change_id]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def _applied_support(retained, by_id, applied_set):
    """Applied transitive dependencies required by the retained IDs.

    G2: a change can only stay applied while its applied prerequisites stay
    applied, so the closure of retained changes is retained too.
    """
    required = set()
    stack = list(retained)
    while stack:
        change_id = stack.pop()
        if change_id in required:
            continue
        required.add(change_id)
        for target in by_id[change_id]["depends_on"]:
            if target in applied_set and target not in required:
                stack.append(target)
    return required


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    # G2 freezes production before graph or change validation, so the
    # environment check runs first and short-circuits everything else.
    try:
        budget = limit_for(request)
    except PolicyError as exc:
        return failure(str(exc))
    try:
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        retained = read_retained(request) if request["action"] == "rollback" else []
        order = _topological_order(changes)
        known = set(order)
        unknown = [change_id for change_id in applied if change_id not in known]
        if unknown:
            raise JournalError("unknown-dependency")
        applied_set = set(applied)
        if any(change_id not in applied_set for change_id in retained):
            raise JournalError("invalid-retain")
    except JournalError as exc:
        return failure(str(exc))

    units_of = {row["id"]: row["units"] for row in changes}
    if request["action"] == "rollback":
        kept = _applied_support(retained, {row["id"]: row for row in changes}, applied_set)
        emitted = [change_id for change_id in reversed(order)
                   if change_id in applied_set and change_id not in kept]
    else:
        emitted = [change_id for change_id in order if change_id not in applied_set]
        if sum(units_of[change_id] for change_id in emitted) > budget:
            return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted,
            "units": sum(units_of[change_id] for change_id in emitted)}

