"""Validate release policy before computing actions."""


class PolicyError(ValueError):
    pass


# G2: this release is staging-only. Production still parses as a known
# environment, but every action against it is frozen.
SUPPORTED_ACTIONS = {
    "staging": frozenset(("plan", "rollback")),
    "production": frozenset(),
}

# G2: the effective staging budget is the smaller of the request budget and
# this ceiling, for plan and rollback alike.
STAGING_BUDGET_CAP = 3


def limit_for(request):
    """Return the effective budget, after environment and action policy.

    This runs before any graph or change validation so that a frozen
    production request fails with `production-frozen` even when its change
    list is malformed.
    """
    environment = request.get("environment")
    if not isinstance(environment, str) or environment not in SUPPORTED_ACTIONS:
        raise PolicyError("invalid-environment")
    if environment == "production":
        raise PolicyError("production-frozen")
    action = request.get("action")
    if not isinstance(action, str) or action not in SUPPORTED_ACTIONS[environment]:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return min(budget, STAGING_BUDGET_CAP)


def supports(environment, action):
    """Whether the environment permits the action at all."""
    if not isinstance(environment, str) or not isinstance(action, str):
        return False
    return action in SUPPORTED_ACTIONS.get(environment, ())

