"""Normalize release records at the input boundary."""


class JournalError(ValueError):
    pass


def _identifier(value):
    return isinstance(value, str) and value != ""


def read_changes(records):
    """Validate, deduplicate and normalize change records.

    Identical duplicates (same id, component, units and dependency set) collapse
    to one row; conflicting duplicates raise ``conflicting-change``.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = []
    seen = {}
    for row in records:
        if (not isinstance(row, dict) or not _identifier(row.get("id"))
                or not _identifier(row.get("component"))
                or type(row.get("units")) is not int or row["units"] < 1):
            raise JournalError("invalid-change")
        depends_on = row.get("depends_on", [])
        if not isinstance(depends_on, list):
            raise JournalError("invalid-change")
        for dep in depends_on:
            if not _identifier(dep):
                raise JournalError("invalid-change")
        change = {
            "id": row["id"],
            "component": row["component"],
            "units": row["units"],
            "depends_on": frozenset(depends_on),
        }
        previous = seen.get(change["id"])
        if previous is not None:
            if previous != change:
                raise JournalError("conflicting-change")
            continue
        seen[change["id"]] = change
        changes.append(change)
    return changes


def read_applied(applied):
    """Validate the persisted release journal and return its unique IDs in order."""
    if applied is None:
        return []
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    order = []
    seen = set()
    for change_id in applied:
        if not _identifier(change_id):
            raise JournalError("invalid-change")
        if change_id in seen:
            continue
        seen.add(change_id)
        order.append(change_id)
    return order

