"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, action_for, effective_plan_budget, environment_for, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _topological_order(changes):
    """Return a deterministic topological order of change IDs.

    Among currently eligible changes the lexicographically smallest ID goes
    first. Missing dependency targets raise ``unknown-dependency`` and any
    cycle raises ``dependency-cycle``.
    """
    known = {change["id"] for change in changes}
    dependents = {change["id"]: [] for change in changes}
    remaining = {}
    for change in changes:
        for dep in change["depends_on"]:
            if dep not in known:
                raise JournalError("unknown-dependency")
        remaining[change["id"]] = len(change["depends_on"])
    for change in changes:
        for dep in change["depends_on"]:
            dependents[dep].append(change["id"])

    eligible = [change_id for change_id, count in remaining.items() if count == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        change_id = heapq.heappop(eligible)
        order.append(change_id)
        for dependent in dependents[change_id]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(eligible, dependent)
    if len(order) != len(known):
        raise JournalError("dependency-cycle")
    return order


def _retained_ids(changes, applied, retain):
    """Return applied IDs that must stay: the retain list plus its applied deps."""
    if not retain:
        return set()
    by_id = {change["id"]: change for change in changes}
    done = set(applied)
    kept = set()
    stack = list(retain)
    while stack:
        change_id = stack.pop()
        if change_id in kept:
            continue
        kept.add(change_id)
        for dep in by_id[change_id]["depends_on"]:
            if dep in done and dep not in kept:
                stack.append(dep)
    return kept


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # Production is frozen before any budget, action, graph or change check.
        environment_for(request)
    except PolicyError as exc:
        return failure(str(exc))
    try:
        budget = limit_for(request)
        action = action_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        retain = read_retain(request.get("retain")) if action == "rollback" else []
        known = {change["id"] for change in changes}
        if any(change_id not in known for change_id in applied):
            raise JournalError("unknown-dependency")
        if any(change_id not in set(applied) for change_id in retain):
            raise JournalError("invalid-retain")
        order = _topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units = {change["id"]: change["units"] for change in changes}
    done = set(applied)
    if action == "rollback":
        kept = _retained_ids(changes, applied, retain)
        actions = [change_id for change_id in reversed(order)
                   if change_id in done and change_id not in kept]
    else:
        actions = [change_id for change_id in order if change_id not in done]
        total = sum(units[change_id] for change_id in actions)
        if total > effective_plan_budget(budget):
            return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": sum(units[i] for i in actions)}

