"""Validate release policy before computing actions."""


class PolicyError(ValueError):
    pass


SUPPORTED_ACTIONS = ("plan", "rollback")

# G2 is a staging-only release: the effective plan budget is capped here.
STAGING_PLAN_LIMIT = 3


def environment_for(request):
    """Validate the target environment; return it.

    Production is frozen in G2, so this check runs before any graph or change
    validation and rejects both ``plan`` and ``rollback``.
    """
    environment = request.get("environment")
    if environment == "production":
        raise PolicyError("production-frozen")
    if environment != "staging":
        raise PolicyError("invalid-environment")
    return environment


def limit_for(request):
    """Validate environment and budget; return the budget as an int."""
    environment_for(request)
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    return budget


def action_for(request):
    """Validate the requested action; return it."""
    action = request.get("action")
    if action not in SUPPORTED_ACTIONS:
        raise PolicyError("unsupported-action")
    return action


def effective_plan_budget(budget):
    """Return the plan budget actually enforced for a staging request."""
    return min(budget, STAGING_PLAN_LIMIT)

