"""JSON transport for the release planner.

Transport only: read one JSON request from stdin, hand it to the planner and
print exactly one JSON object. Every request, including domain errors and
malformed input, exits normally.
"""
import json
import sys

from planner import build_result


def dispatch(text):
    try:
        request = json.loads(text)
    except (ValueError, TypeError):
        return {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    return build_result(request)


def main():
    result = dispatch(sys.stdin.read())
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

