"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


class PlannerError(ValueError):
    """Graph-level failures: `unknown-dependency` and `dependency-cycle`."""


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def check_graph(applied, changes):
    """Validate the dependency journal and build the edge sets.

    `graph` maps an id to the ids it depends on. `applied` is the caller's
    persisted journal: trusting an id that is not in `changes` would let a
    corrupt journal silently satisfy dependencies, so unknown ids fail here
    before any ordering or accounting happens.
    """
    for change_id in applied:
        if change_id not in changes:
            raise PlannerError("unknown-dependency")
    graph = {}
    for change_id, change in changes.items():
        if not change.depends_on <= changes.keys():
            raise PlannerError("unknown-dependency")
        graph[change_id] = set(change.depends_on)
    return graph


def topo_order(graph):
    """Return a deterministic topological order of every node in `graph`.

    A min-heap of currently eligible ids gives SPEC.md's lexicographic
    tie-breaking: we always emit the smallest id whose dependencies are done.
    Every node is ordered even when the cycle covers only part of the graph, so
    a cycle is detected wherever it sits. Kahn's count is compared against the
    node total instead of relying on the heap running dry mid-loop.
    """
    remaining = {node: len(deps) for node, deps in graph.items()}
    dependents = {node: [] for node in graph}
    for node, deps in graph.items():
        for dep in deps:
            dependents[dep].append(node)
    ready = [node for node, count in remaining.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(graph):
        raise PlannerError("dependency-cycle")
    return order


def plan(request):
    """Assemble the success/failure object; every failure carries no actions."""
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        graph = check_graph(applied, changes)
        order = topo_order(graph)
    except (PolicyError, JournalError, PlannerError) as exc:
        return failure(str(exc))
    if budget is None:
        # rollback: reverse of the full order, limited to applied changes. The
        # budget was validated by policy but deliberately not applied as a cap.
        emitted = [node for node in reversed(order) if node in applied]
    else:
        # plan: unapplied changes in topological form. Already applied entries
        # satisfy dependencies without entering the action list or the budget.
        emitted = [node for node in order if node not in applied]
        units = sum(changes[node].units for node in emitted)
        if units > budget:
            return failure("budget-exceeded")
    return {"status": "ok", "actions": emitted,
            "units": sum(changes[node].units for node in emitted)}

