"""Normalize release records at the input boundary."""
from dataclasses import dataclass


class JournalError(ValueError):
    pass


class RetainError(ValueError):
    """Malformed or nonapplied rollback `retain`; carried as `invalid-retain`."""

    code = "invalid-retain"


@dataclass(frozen=True)
class Change:
    """One release change after validation and replay collapse.

    `depends_on` is a frozenset because SPEC.md defines record equality over the
    *set* of dependencies: `["a","a"]` and `["a"]` are the same record and must
    collapse. Hashability is what lets `read_changes` detect the conflict below
    without rebuilding the comparison by hand.
    """

    id: str
    component: str
    units: int
    depends_on: frozenset


def _id_list(value):
    """Validate a raw id list; malformed input must not reach the graph."""
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    ids = []
    for item in value:
        if not isinstance(item, str) or not item:
            raise JournalError("invalid-change")
        ids.append(item)
    return ids


def read_change(row):
    """Read one record; `units` must be a positive int and bools never count as int."""
    if (not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"]
            or not isinstance(row.get("component"), str) or not row["component"]
            or type(row.get("units")) is not int or row["units"] < 1):
        raise JournalError("invalid-change")
    return Change(
        id=row["id"],
        component=row["component"],
        units=row["units"],
        depends_on=frozenset(_id_list(row.get("depends_on", []))),
    )


def read_changes(records):
    """Return the deduplicated change set keyed by id.

    Duplicates are collapsed before graph construction and accounting, so a
    repeated record neither charges budget twice nor contributes a second node.
    The same id with any different component/units/dependency set is a conflict:
    the journal is the caller's persisted identity, so we never pick a winner.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        change = read_change(row)
        seen = changes.get(change.id)
        if seen is None:
            changes[change.id] = change
        elif seen != change:
            raise JournalError("conflicting-change")
    return changes


def read_applied(rows):
    """Return the caller-supplied applied journal as a frozenset of ids."""
    return frozenset(_id_list(rows))


def read_retain(request, applied):
    """Return the rollback `retain` set, defaulting to empty.

    G2 keeps `retain` meaningful only for `rollback`. Instead of validating it on
    plan and throwing it away, the whole field is ignored there -- that is the
    decided compatibility rule: an otherwise valid plan must not start failing
    because a caller passed a `retain` shaped for a later rollback.

    On rollback the list must be a string array (same `_id_list` scale as
    `applied`, so non-array/non-string/empty members and booleans all fail) and
    every member must already be applied: retaining something that was never
    released has no closure to protect, so it is rejected rather than silently
    widened. The error is `invalid-retain`, distinct from the journal's
    `invalid-change`, because it names a different field and a different fix.
    """
    if request.get("action") != "rollback":
        return frozenset()
    if "retain" not in request:
        return frozenset()
    try:
        retained = _id_list(request["retain"])
    except JournalError:
        raise RetainError()
    # Unknown ids cannot reach here: the planner checks `applied` against the
    # change set before calling this, so membership is tested against that set.
    if not set(retained) <= applied:
        raise RetainError()
    return frozenset(retained)

